css:
:root{--navy:#080c14;--navy2:#0f1623;--blue:#0a63c4;--gold:#c9a24b;--ivory:#f7f4ed;--ink:#1b2230;--mute:#5d6572;--r:2px;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
html{scroll-behavior:smooth;scroll-padding-top:90px}*{box-sizing:border-box}
body{margin:0;font:17px/1.7 var(--font-lato,'Lato'),Helvetica,Arial,sans-serif;color:var(--ink);background:var(--ivory)}
h1,h2,h3{font-family:var(--font-playfair,'Playfair Display'),Georgia,serif;font-weight:700;line-height:1.2;margin:0}
a{color:inherit;text-decoration:none}
.wrap{max-width:1160px;margin:auto;padding:0 24px}
.hlogo{width:min(400px,80%);height:auto;margin:0 auto 28px;display:block}
.btn{display:inline-block;padding:14px 30px;font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;border:1px solid var(--gold);border-radius:var(--r);transition:.2s}
.btn.fill{background:var(--gold);color:#16120a}.btn.fill:hover{background:#dbb862}
.btn.line{color:#fff;border-color:rgba(255,255,255,.7)}.btn.line:hover{background:#fff;color:var(--navy)}
.hero{position:relative;color:#fff;text-align:center;padding:90px 0 120px;background:linear-gradient(rgba(8,12,20,.72),rgba(8,12,20,.82)),url(/assets/hero-bg.jpg) center/cover}
.eyebrow{font-size:13px;font-weight:700;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin-bottom:16px;display:block}
.hero h1{font-size:clamp(38px,6vw,68px);max-width:860px;margin:0 auto 18px}
.hero p{max-width:600px;margin:0 auto 36px;font-size:19px;color:#d6d9e0}
.hero .row{display:flex;gap:16px;justify-content:center;flex-wrap:wrap}
.rule{width:64px;height:2px;background:var(--gold);margin:18px 0 0}
section{padding:96px 0}
section.white{background:#fff}
.center{text-align:center}.center .rule{margin:18px auto 0}
h2{font-size:clamp(30px,4vw,42px)}
.eyebrow.b{color:var(--blue)}
.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));margin-top:56px;border-top:1px solid #ddd8ca}
.col{padding:36px 28px;border-left:1px solid #ddd8ca;text-align:left}
.col:first-child{border-left:0}
.ico{width:46px;height:46px;border:1px solid var(--gold);display:grid;place-items:center;margin-bottom:20px;color:var(--blue);font:700 18px var(--font-playfair,'Playfair Display'),serif}
.ico svg{width:20px;height:20px;display:block}
.col h3{font-size:21px;margin-bottom:10px}.col p{margin:0;color:var(--mute);font-size:16px}
.split{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.split img{width:100%;display:block;border:1px solid var(--gold);padding:10px;background:#fff;box-shadow:0 20px 40px rgba(8,12,20,.18)}
.split p{color:var(--mute);margin:22px 0 28px}
.split p.tight{margin-top:-8px}
@media(max-width:820px){.split{grid-template-columns:1fr;gap:36px}.col{border-left:0;border-bottom:1px solid #ddd8ca}}
.cta{text-align:center;padding:84px 0;background:linear-gradient(120deg,#07204a,#0a4a9a);color:#fff;border-block:1px solid var(--gold)}
.cta h2{margin-bottom:28px}
section.white .btn.fill{color:#16120a}
section .btn.fill{color:#16120a}
#services .btn.fill{color:#16120a}
